package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for TypeBindings.create(Class<?> erasedType, JavaType typeArg1)
 */
public class TypeBindings_create_TriageGen1Test {

    private final TypeFactory typeFactory = TypeFactory.defaultInstance();

    // Helper classes to test TypeParamStash behavior
    static class SingleTypeParam<T> {}
    static class MultipleTypeParams<T, U> {}
    static class NoTypeParams {}

    @Test
    public void testCreate_Success() {
        // Arrange
        Class<?> erasedType = SingleTypeParam.class;
        JavaType typeArg1 = typeFactory.constructType(String.class);

        // Act
        TypeBindings result = TypeBindings.create(erasedType, typeArg1);

        // Assert
        Assert.assertNotNull(result);
        assertEquals(1, result.size());

        // Verify the variable name matches the first parameter of SingleTypeParam<T>
        // Note: TypeParamStash.paramsFor1(erasedType) is used internally
        String boundName = result.getBoundName(0);
        Assert.assertNotNull(boundName);
        assertEquals(typeArg1, result.getBoundType(0));
    }

    @Test
    public void testCreate_ThrowsIllegalArgumentException_WhenMultipleParams() {
        // Arrange
        Class<?> erasedType = MultipleTypeParams.class;
        JavaType typeArg1 = typeFactory.constructType(String.class);

        // Act & Assert
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            TypeBindings.create(erasedType, typeArg1);
        });

        // Verify error message contains expected information
        String expectedMessagePart = "class " + erasedType.getName() + " with 1 type parameter: class expects 2";
        Assert.assertTrue(exception.getMessage().contains(expectedMessagePart));
    }

    @Test
    public void testCreate_ThrowsIllegalArgumentException_WhenNoParams() {
        // Arrange
        Class<?> erasedType = NoTypeParams.class;
        JavaType typeArg1 = typeFactory.constructType(String.class);

        // Act & Assert
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            TypeBindings.create(erasedType, typeArg1);
        });

        // Verify error message contains expected information
        String expectedMessagePart = "class " + erasedType.getName() + " with 1 type parameter: class expects 0";
        Assert.assertTrue(exception.getMessage().contains(expectedMessagePart));
    }

    @Test
    public void testCreate_ThrowsNullPointerException_WhenErasedTypeIsNull() {
        // Arrange
        JavaType typeArg1 = typeFactory.constructType(String.class);

        // Act & Assert
        // Since TypeParamStash.paramsFor1(erasedType) is called, passing null will trigger NPE
        assertThrows(NullPointerException.class, () -> {
            TypeBindings.create(null, typeArg1);
        });
    }

    @Test
    public void testCreate_ThrowsNullPointerException_WhenTypeArgIsNull() {
        // Arrange
        Class<?> erasedType = SingleTypeParam.class;

        // Act & Assert
        // The method doesn't check for null typeArg1 explicitly, but the constructor 
        // or subsequent usage might, however, the current code allows it to be passed.
        // We test the behavior of the current implementation.
        TypeBindings result = TypeBindings.create(erasedType, null);
        Assert.assertNotNull(result);
        assertEquals(null, result.getBoundType(0));
    }
}
